#include <cassert>
#include <ranges>
#include <string>
#include <fmt/ranges.h>
struct X {
  template <std::ranges::range R>
  X(R&& r) : sv(&*std::ranges::begin(r), std::ranges::distance(r)) {}
  auto begin() { return sv.begin(); }
  auto end() { return sv.end(); }
  std::string_view sv;
};
int main() {
  std::string line = "a,b-c,d-e,f";
  const std::string expected = "[['a'], ['b', '-', 'c'], ['d', '-', 'e'], ['f']]";
  assert(fmt::format("{}", line | std::views::split(',')) == expected);
  auto x = line | std::views::split(',') | std::views::transform([](auto part) { return X(part); });
  assert(fmt::format("{}", x) == expected);
  auto y = line | std::views::split(',') | std::views::transform(std::views::split('-'));
  assert(fmt::format("{}", y) == "[[['a']], [['b'], ['c']], [['d'], ['e']], [['f']]]");
  fmt::print("{}\n{}\n{}\n", line | std::views::split(','), x, y);
}
EOF
